package com.uop.recordingtools.command;
import com.uop.recordingtools.UopRecordingToolsPlugin; import com.uop.recordingtools.util.*; import org.bukkit.*; import org.bukkit.command.*; import org.bukkit.enchantments.Enchantment; import org.bukkit.entity.Player; import org.bukkit.inventory.ItemStack; import java.util.*;
public final class UopCommand implements CommandExecutor,TabCompleter{
 private final UopRecordingToolsPlugin p;private final List<String> roots=List.of("armor","checkpoint","damage","disenchant","enchant","freeze","unfreeze","inv","help","name","permission","protect","reload","reset","version");public UopCommand(UopRecordingToolsPlugin p){this.p=p;}
 private boolean admin(CommandSender s){return !(s instanceof Player)||s.isOp();}private boolean allow(CommandSender s,String perm){return admin(s)||s.hasPermission(perm)||(s instanceof Player x&&p.permissions().has(x,perm));}private void msg(CommandSender s,String m){s.sendMessage(ChatColor.translateAlternateColorCodes('&',"&7[&bUOP&7] "+m));}
 @Override public boolean onCommand(CommandSender s,Command c,String l,String[] a){try{return run(s,a);}catch(Exception e){msg(s,"&cCommand error: "+e.getMessage());p.getLogger().warning("/uop error: "+e);return true;}}
 private boolean run(CommandSender s,String[] a){if(!admin(s)&&s instanceof Player x&&!p.permissions().has(x,"uop.use")){msg(s,"&cYou do not have permission to use UOP Recording Tools.");return true;}if(a.length==0){help(s);return true;}String r=a[0].toLowerCase(Locale.ROOT);switch(r){case "help"->help(s);case "version"->msg(s,"&fUOP Recording Tools &b"+p.getDescription().getVersion()+" &7for Paper 1.21.11");case "reload"->{if(!admin(s)){msg(s,"&cOP/console only.");break;}p.reloadPlugin();msg(s,"&aReloaded.");}case "reset"->reset(s,a);case "armor"->armor(s,a);case "checkpoint"->checkpoint(s,a);case "damage"->damage(s,a);case "enchant"->ench(s,a,false);case "disenchant"->ench(s,a,true);case "freeze"->freeze(s,a,false);case "unfreeze"->freeze(s,a,true);case "inv"->inv(s,a);case "name"->name(s,a);case "protect"->protect(s,a);case "permission"->permission(s,a);default->msg(s,"&cUnknown command. Use /uop help.");}return true;}
 private void need(CommandSender s,String perm){if(!allow(s,perm))throw new IllegalStateException("You do not have permission: "+perm);}private void help(CommandSender s){msg(s,"&f/uop armor &7| checkpoint | damage | enchant | disenchant | freeze | unfreeze");msg(s,"&f/uop inv &7| name | protect | permission | reload | reset | version");}
 private void reset(CommandSender s,String[] a){if(!admin(s)){msg(s,"&cOP/console only.");return;}if(a.length>1&&!a[1].equalsIgnoreCase("all")){msg(s,"&cUse /uop reset all");return;}p.store().data().set("damage",null);p.store().data().set("freeze",null);p.store().data().set("checkpoints",null);p.store().data().set("loadouts",null);p.store().data().set("tags",null);p.store().data().set("names",null);p.store().data().set("protection",null);p.store().data().set("permissions",null);p.store().data().set("inventories",null);p.store().saveNow();for(Player x:Bukkit.getOnlinePlayers()){p.freeze().unfreeze(x);p.names().refresh(x);}msg(s,"&aAll UOP persistent state reset.");}
 private List<Player> targets(CommandSender s,String token){List<Player> ps=Targets.players(s,token);if(ps.isEmpty())throw new IllegalArgumentException("No matching players: "+token);return ps;}
 private void armor(CommandSender s,String[] a){need(s,"uop.armor");if(a.length<2){msg(s,"&f/uop armor set|save|list|delete|give|weapon");return;}switch(a[1].toLowerCase()){case "set"->armorSet(s,a);case "save"->{if(a.length<4)throw new IllegalArgumentException("/uop armor save <set_name> <player>");Player q=Targets.one(s,a[3]);if(q==null)throw new IllegalArgumentException("Player not found");p.armor().saveLoadout(a[2],q);msg(s,"&aSaved loadout "+a[2]);}case "list"->msg(s,"&fLoadouts: &7"+String.join(", ",p.armor().loadouts()));case "delete"->{if(a.length<3)throw new IllegalArgumentException("Name required");p.armor().delete(a[2]);msg(s,"&aDeleted.");}case "give"->armorGive(s,a);case "weapon"->weapon(s,a);default->msg(s,"&cUnknown armor action.");}}
 private void armorSet(CommandSender s,String[] a){if(a.length<5)throw new IllegalArgumentException("/uop armor set <targets> <material> <mode> [true|false] [weapons...]");List<Player> ps=targets(s,a[2]);String mat=a[3],mode=a[4];boolean weapons=a.length>5&&Boolean.parseBoolean(a[5]);List<String> ws=a.length>6?Arrays.asList(a).subList(6,a.length):List.of();for(Player q:ps)p.armor().set(q,mat,mode,weapons,ws);msg(s,"&aArmor set applied to "+ps.size()+" player(s).");}
 private void armorGive(CommandSender s,String[] a){if(a.length<4)throw new IllegalArgumentException("/uop armor give <targets> direct|saved ...");List<Player> ps=targets(s,a[2]);if(a[3].equalsIgnoreCase("saved")){if(a.length<5)throw new IllegalArgumentException("Loadout name required");for(Player q:ps)if(!p.armor().giveSaved(a[4],q))msg(s,"&cLoadout not found: "+a[4]);}else{if(a.length<6)throw new IllegalArgumentException("Direct requires material and mode");boolean weapons=a.length>6&&Boolean.parseBoolean(a[6]);List<String> ws=a.length>7?Arrays.asList(a).subList(7,a.length):List.of();for(Player q:ps)p.armor().set(q,a[4],a[5],weapons,ws);}msg(s,"&aLoadout applied.");}
 private void weapon(CommandSender s,String[] a){if(a.length<5)throw new IllegalArgumentException("/uop armor weapon set <targets> <mode> <weapons...>");if(!a[2].equalsIgnoreCase("set"))throw new IllegalArgumentException("Use weapon set");List<Player> ps=targets(s,a[3]);String mode=a[4];int lvl=Items.level(mode,mode);List<String> ws=Arrays.asList(a).subList(5,a.length);for(Player q:ps)p.armor().giveWeapons(q,ws,mode,lvl);}
 private void checkpoint(CommandSender s,String[] a){need(s,"uop.checkpoint");if(a.length<2){msg(s,"&f/uop checkpoint save|tp|list|delete|clear");return;}switch(a[1].toLowerCase()){case "save"->{if(!(s instanceof Player))throw new IllegalArgumentException("Player required");if(a.length<3)throw new IllegalArgumentException("Name required");List<Player> ps=a.length>3?targets(s,a[3]):List.of((Player)s);p.checkpoints().save(a[2],ps);msg(s,"&aCheckpoint saved.");}case "tp"->{if(!(s instanceof Player))throw new IllegalArgumentException("Player required");if(a.length<3)throw new IllegalArgumentException("Name required");if(!p.checkpoints().tp(a[2],List.of((Player)s)))msg(s,"&cCheckpoint not found.");}case "list"->msg(s,"&fCheckpoints: &7"+String.join(", ",p.checkpoints().list()));case "delete"->{p.checkpoints().delete(a[2]);msg(s,"&aDeleted.");}case "clear"->{if(a.length>2&&!a[2].equalsIgnoreCase("all"))throw new IllegalArgumentException("Use clear all");p.checkpoints().clear();msg(s,"&aCleared.");}default->msg(s,"&cUnknown checkpoint action.");}}
 private double num(String x){try{return Double.parseDouble(x);}catch(Exception e){throw new IllegalArgumentException("Invalid number: "+x);}}
 private void damage(CommandSender s,String[] a){need(s,"uop.damage");if(a.length<2){msg(s,"&f/uop damage global|outgoing|incoming|set|reset");return;}switch(a[1].toLowerCase()){case "global"->p.damage().global(num(a[2]));case "outgoing"->{Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");p.damage().outgoing(q,num(a[3]));}case "incoming"->{Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");p.damage().incoming(q,num(a[3]));}case "set"->{Player x=Targets.one(s,a[2]),y=Targets.one(s,a[3]);if(x==null||y==null)throw new IllegalArgumentException("Players not found");p.damage().pair(x,y,num(a[4]));}case "reset"->damageReset(s,a);default->throw new IllegalArgumentException("Unknown damage action");}msg(s,"&aDamage rule updated.");}
 private void damageReset(CommandSender s,String[] a){if(a.length<3)throw new IllegalArgumentException("Reset type required");String t=a[2].toLowerCase();if(t.equals("global")||t.equals("all")){p.damage().resetAll();return;}Player x=Targets.one(s,a.length>3?a[3]:"");if(x==null)throw new IllegalArgumentException("Player not found");if(t.equals("pair")){Player y=Targets.one(s,a[4]);if(y==null)throw new IllegalArgumentException("Player not found");p.damage().reset("pair",x,y);}else p.damage().reset(t,x,null);}
 private void ench(CommandSender s,String[] a,boolean remove){need(s,remove?"uop.disenchant":"uop.enchant");if(a.length<4)throw new IllegalArgumentException("Invalid syntax");String scope=a[1];List<Player> ps=targets(s,a[2]);String slot=null,enchName;int level=1;if(remove){if(scope.equalsIgnoreCase("armor")||scope.equalsIgnoreCase("equipment")||scope.equalsIgnoreCase("hand")){slot=a[3];enchName=a[4];}else enchName=a[3];}else enchName=a[3];Enchantment e=Items.enchantment(enchName);if(e==null)throw new IllegalArgumentException("Unknown enchantment: "+enchName);if(!remove&&a.length>4)try{level=Math.max(1,Math.min(255,Integer.parseInt(a[4])));}catch(Exception ignored){}for(Player q:ps)if(remove)p.enchant().remove(q,scope,e,slot);else p.enchant().apply(q,scope,e,level,slot);msg(s,"&aDone for "+ps.size()+" player(s).");}
 private void freeze(CommandSender s,String[] a,boolean unfreeze){need(s,"uop.freeze");if(a.length<2)throw new IllegalArgumentException("Targets required");String mode="normal",target=a[1];if(!unfreeze&&(a[1].equalsIgnoreCase("normal")||a[1].equalsIgnoreCase("full"))){mode=a[1];if(a.length<3)throw new IllegalArgumentException("Targets required");target=a[2];}List<Player> ps=targets(s,target);for(Player q:ps){if(unfreeze)p.freeze().unfreeze(q);else p.freeze().freeze(q,mode);}msg(s,"&aFreeze state updated for "+ps.size()+" player(s).");}
 private void inv(CommandSender s,String[] a){need(s,"uop.inv");if(a.length<2){msg(s,"&f/uop inv view|set|remove|give|take|swap|clear|backup|restore|backups|backup-delete|record|back|lock|unlock");return;}switch(a[1].toLowerCase()){case "view"->{Player q=Targets.one(s,a[2]);if(q==null)throw new IllegalArgumentException("Player not found");if(s instanceof Player x)x.openInventory(q.getInventory());}case "set"->{Player q=Targets.one(s,a[2]);int slot=Integer.parseInt(a[3]);Material m=Material.matchMaterial(a[4]);if(q==null||m==null)throw new IllegalArgumentException("Invalid target/item");int n=a.length>5?Integer.parseInt(a[5]):1;p.inventory().set(q,slot,new ItemStack(m,Math.max(1,Math.min(99,n))));}case "remove"->{Player q=Targets.one(s,a[2]);p.inventory().remove(q,Integer.parseInt(a[3]));}case "give"->{Player q=Targets.one(s,a[2]);Material m=Material.matchMaterial(a[3]);p.inventory().give(q,m,a.length>4?Integer.parseInt(a[4]):1);}case "take"->{Player q=Targets.one(s,a[2]);Material m=Material.matchMaterial(a[3]);p.inventory().take(q,m,a.length>4?Integer.parseInt(a[4]):1);}case "swap"->{Player x=Targets.one(s,a[2]),y=Targets.one(s,a[4]);p.inventory().swap(x,Integer.parseInt(a[3]),y,Integer.parseInt(a[5]));}case "clear"->p.inventory().clear(Targets.one(s,a[2]));case "backup"->{Player q=Targets.one(s,a[2]);p.inventory().backup(q,a[3]);}case "restore"->{Player q=Targets.one(s,a[2]);if(!p.inventory().restore(q,a[3]))msg(s,"&cBackup not found.");}case "backups"->{Player q=Targets.one(s,a[2]);msg(s,"&fBackups: &7"+String.join(", ",p.inventory().backups(q)));}case "backup-delete"->{Player q=Targets.one(s,a[2]);p.inventory().backupDelete(q,a[3]);}case "record"->{if(a.length>2&&a[2].equalsIgnoreCase("status")){msg(s,"&fRecording players: &7"+p.inventory().recording().size());break;}if(a.length>2&&a[2].equalsIgnoreCase("stop")){for(Player q:targets(s,a[3]))p.inventory().stopRecord(List.of(q));}else for(Player q:targets(s,a[2]))p.inventory().startRecord(List.of(q));}case "back"->{Player q=Targets.one(s,a[2]);if(!p.inventory().back(q,a[3]))msg(s,"&cNo history available.");}case "lock"->{Player q=Targets.one(s,a[2]);p.inventory().lock(q,true);}case "unlock"->{Player q=Targets.one(s,a[2]);p.inventory().lock(q,false);}default->throw new IllegalArgumentException("Unknown inventory action");}msg(s,"&aInventory operation complete.");}
 private void name(CommandSender s,String[] a){need(s,"uop.name");if(a.length<2){msg(s,"&f/uop name hide|show|tag");return;}switch(a[1].toLowerCase()){case "hide","show"->{for(Player q:targets(s,a[2]))if(a[1].equalsIgnoreCase("hide"))p.names().hide(q);else p.names().show(q);}case "tag"->tag(s,a);default->throw new IllegalArgumentException("Unknown name action");}msg(s,"&aName operation complete.");}
 private void tag(CommandSender s,String[] a){if(a.length<3||a[2].equalsIgnoreCase("help")){msg(s,"&f/uop name tag create|edit|list|give|change|remove|delete");return;}switch(a[2].toLowerCase()){case "create","edit"->{if(a.length<8)throw new IllegalArgumentException("create/edit <id> <color> <bold> <italic> <text>");String text=String.join(" ",Arrays.asList(a).subList(7,a.length));if(a[2].equalsIgnoreCase("create"))p.names().create(a[3],a[4],Boolean.parseBoolean(a[5]),Boolean.parseBoolean(a[6]),text);else p.names().edit(a[3],a[4],Boolean.parseBoolean(a[5]),Boolean.parseBoolean(a[6]),text);}case "list"->msg(s,"&fTags: &7"+String.join(", ",p.names().tags()));case "give","change"->{List<Player> ps=targets(s,a[3]);for(Player q:ps)p.names().give(q,a[4]);}case "remove"->{for(Player q:targets(s,a[3]))p.names().removeTag(q);}case "delete"->p.names().deleteTag(a[3]);default->throw new IllegalArgumentException("Unknown tag action");}}
 private void protect(CommandSender s,String[] a){need(s,"uop.protect");if(a.length<2)throw new IllegalArgumentException("Action required");switch(a[1].toLowerCase()){case "add","uuid","ip","both"->{for(Player q:targets(s,a[2]))p.protection().add(q,a[1].equalsIgnoreCase("add")?"both":a[1]);}case "remove"->{for(Player q:targets(s,a[2]))p.protection().remove(q);}case "list"->msg(s,"&fProtected names: &7"+String.join(", ",p.protection().list()));case "reset"->p.protection().reset();default->throw new IllegalArgumentException("Unknown protection action");}msg(s,"&aProtection updated.");}
 private void permission(CommandSender s,String[] a){if(!admin(s)){msg(s,"&cPermission administration is restricted to actual OPs/server console.");return;}if(a.length<2)throw new IllegalArgumentException("grant|revoke|list|check|reset");switch(a[1].toLowerCase()){case "grant","revoke"->{Player q=Targets.one(s,a[2]);String[] nodes=Arrays.copyOfRange(a,3,a.length);if(a[1].equalsIgnoreCase("grant"))p.permissions().grant(q,nodes);else p.permissions().revoke(q,nodes);}case "list"->{Player q=Targets.one(s,a[2]);msg(s,"&fPermissions for "+q.getName()+": &7"+String.join(", ",p.permissions().list(q)));}case "check"->{Player q=Targets.one(s,a[2]);msg(s,"&f"+q.getName()+": "+p.permissions().has(q,a[3]));}case "reset"->{if(a[2].equalsIgnoreCase("all")){p.store().data().set("permissions",null);p.store().saveNow();}else{Player q=Targets.one(s,a[2]);p.permissions().reset(q,a.length>3?a[3]:null);}}default->throw new IllegalArgumentException("Unknown permission action");}msg(s,"&aPermission operation complete.");}
 @Override public List<String> onTabComplete(CommandSender s,Command c,String alias,String[] a){String prefix=a.length==0?"":a[a.length-1].toLowerCase(Locale.ROOT);List<String> out=new ArrayList<>();if(a.length==1)return roots.stream().filter(x->x.startsWith(prefix)).toList();String root=a[0].toLowerCase();switch(root){case "armor"->armorTab(a,out);case "checkpoint"->simple(a,out,List.of("save","tp","list","delete","clear"));case "damage"->simple(a,out,List.of("global","outgoing","incoming","set","reset"));case "enchant","disenchant"->simple(a,out,List.of("all","armor","equipment","mainhand","offhand","inventory","hand"));case "freeze"->simple(a,out,List.of("normal","full","all"));case "unfreeze"->players(out);case "inv"->simple(a,out,List.of("view","set","remove","give","take","swap","clear","backup","restore","backups","backup-delete","record","back","lock","unlock"));case "name"->simple(a,out,List.of("hide","show","tag"));case "protect"->simple(a,out,List.of("add","uuid","ip","both","remove","list","reset"));case "permission"->simple(a,out,List.of("grant","revoke","list","check","reset"));}return out.stream().filter(x->x.toLowerCase().startsWith(prefix)).distinct().sorted().toList();}
 private void simple(String[] a,List<String> o,List<String> vals){if(a.length==2)o.addAll(vals);else players(o);}private void armorTab(String[] a,List<String> o){if(a.length==2)o.addAll(List.of("set","save","list","delete","give","weapon"));else if(a.length==3)players(o);else if(a.length==4)o.addAll(List.of("leather","chainmail","iron","gold","diamond","netherite","direct","saved"));else if(a.length==5)o.addAll(List.of("plain","enchanted","max","false","true"));else o.addAll(List.of("false","true","sword","mace","axe","bow","crossbow","trident","pickaxe","shovel","hoe"));}private void players(List<String> o){o.addAll(Bukkit.getOnlinePlayers().stream().map(Player::getName).toList());o.addAll(List.of("@a","@p","@r","@s"));}
}
